  ('ipeds-2024', 'NCES, U.S. Department of Education', 'IPEDS Institutional Characteristics: Directory Information (HD2024) and Educational offerings, organization, services and athletic associations (IC2024)', '2024-25 collection', 'https://nces.ed.gov/ipeds/datacenter/data/HD2024.zip; https://nces.ed.gov/ipeds/datacenter/data/IC2024.zip', '2026-10-12', 'HD2024.zip d98425c123d7c0e872aec6e83960dfb501884818bf17385c340790f3d1f28345; IC2024.zip 924f04f0afd953633a34bbc2ad1beaa65fdbf2a7ba25ebe364bac7469a976288', 'States NE, KS, IA, ND, SD; schools reporting membership in a national athletic association (IC2024 ATHASSOC = 1). Associations from IC2024 ASSOC1 to ASSOC6 as reported by each school to the Department of Education, not from the associations themselves.'),
  ('cip-2020', 'NCES, U.S. Department of Education', 'Classification of Instructional Programs (CIP)', 'CIP 2020', 'https://nces.ed.gov/ipeds/cipcode/Files/CIPCode2020.csv', '2026-10-12', 'CIPCode2020.csv 6cf0882c1f5beb94981d0a1a72285ab5cf633759f45433fb909afbfb6d6b2657', '4-digit codes only. Dropped: codes marked Deleted or Moved to, and families 21, 32 to 37, 53, 55, 60, 61 (not college majors).'),
  ('pi-nicknames-v1', 'Proven Impact', 'Hand-kept school nicknames for search (supabase/reference/college-nicknames.json)', 'v1', null, '2026-10-12', null, 'Added to the IPEDS aliases, which are incomplete (for example UNO is listed only as UNOMAHA).')
